using Pragmatic.SourceGen;
using Pragmatic.SourceGenerator.Core;
using Pragmatic.SourceGenerator.Features.Traits.Models;

namespace Pragmatic.SourceGenerator.Features.Traits.Templates;

/// <summary>
/// Generates tag DomainAction classes (Add, Remove).
/// The Invoker + SetDependencies are generated by ActionsFeature from the corresponding ActionModel.
/// </summary>
internal sealed partial class TagActionsTemplate : CSharpTemplate
{
    private readonly TagTraitModel _model;
    private readonly string _actionTypeName;
    private readonly TagActionKind _kind;
    private readonly bool _engine;
    private readonly bool _serializable;

    /// <param name="model">The tag trait.</param>
    /// <param name="kind">The action.</param>
    /// <param name="engine">
    ///     True for tags the Sql or documents engine persists: the action reads and writes through the tag's and the link's repositories
    ///     (<c>TagActionsTemplate.Engine.cs</c>) instead of EF Core's <c>DbContext</c>.
    /// </param>
    /// <param name="serializable">
    ///     On the Sql engine with a per-entity limit: the add runs in a serializable transaction of the session, as with EF Core, so the count and
    ///     the insert are indivisible.
    /// </param>
    public TagActionsTemplate(TagTraitModel model, TagActionKind kind, bool engine = false, bool serializable = false)
    {
        _model = model;
        _kind = kind;
        _engine = engine;
        _serializable = serializable;
        _actionTypeName = kind switch
        {
            TagActionKind.Add => $"Add{model.ParentTypeName}TagAction",
            TagActionKind.Remove => $"Remove{model.ParentTypeName}TagAction",
            _ => throw new ArgumentOutOfRangeException(nameof(kind))
        };
    }

    protected override string? GeneratorName => "Pragmatic.SourceGenerator/Traits";
    protected override string? TriggerInfo => $"[HasTags] {_kind} action for {_model.ParentTypeName}";

    public override Artifact RenderOutput()
        => new(VirtualFolderHints.ForType(_actionTypeName, "Action", _model.ParentNamespace), ToSourceText());

    public override void RenderFile()
    {
        AddUsing("System.Linq");
        if (!_engine)
            AddUsing("Microsoft.EntityFrameworkCore");
        AddUsing("Microsoft.Extensions.DependencyInjection");
        AddUsing("Pragmatic.Actions.Abstractions");
        AddUsing("Pragmatic.Actions.Attributes");
        // [BelongsTo<T>] lives in Persistence, not beside [DomainAction].
        AddUsing("Pragmatic.Persistence.Entity");
        AddUsing("Pragmatic.Identity");
        AddUsing("Pragmatic.Tags");
        AddUsing("Pragmatic.Result");
        AddUsing("Pragmatic.Result.Http");
        AddUsing("Pragmatic.Temporal.Clock");

        AppendNamespace(_model.ParentNamespace);
        AppendLine();

        var baseType = _kind == TagActionKind.Add
            ? "DomainAction<Guid>"
            : "VoidDomainAction";

        XmlSummary($"SG-generated action: {(_kind == TagActionKind.Add ? "adds" : "removes")} a tag on <see cref=\"{_model.ParentTypeName}\"/>.");
        AppendLine("[DomainAction]");
        if (_model.BoundaryFullTypeName is not null)
            AppendLine($"[BelongsTo<global::{_model.BoundaryFullTypeName}>]");

        Class(_actionTypeName, RenderBody,
            accessModifier: AccessModifier.Public,
            modifiers: new ClassModifiers { Partial = true, Sealed = true },
            baseType: baseType);
    }

    private void RenderBody()
    {
        if (_engine)
        {
            RenderEngineBody();
            return;
        }

        AppendLine("private DbContext _db = null!;");
        if (_kind == TagActionKind.Add)
        {
            AppendLine("private ICurrentUser _currentUser = null!;");
            AppendLine("private IClock _clock = null!;");
        }

        // The policy is optional, so it is resolved on demand from the application service
        // provider — injecting it directly would make it a required constructor dependency.
        AppendLine("private global::System.IServiceProvider _services = null!;");
        AppendLine();

        switch (_kind)
        {
            case TagActionKind.Add: RenderAddBody(); break;
            case TagActionKind.Remove: RenderRemoveBody(); break;
        }

        if (_kind == TagActionKind.Add && _model.MaxPerEntity > 0)
            RenderSerializationConflictDetector();
    }

    /// <summary>The tag's scope as a literal: the trait's override, else the parent's name.</summary>
    private string ScopeLiteral => _model.ScopeOverride is not null ? $"\"{_model.ScopeOverride}\"" : $"\"{_model.ParentTypeName}\"";

    /// <summary>The policy resolved, a disallowed value refused, and <c>normalizedValue</c> and <c>displayValue</c> declared: the add's opening on every engine.</summary>
    private void RenderPolicyGateAndNormalize()
    {
        RenderPolicyResolve();

        // Validation gate — reject disallowed tag values (ITagPolicy.IsAllowedAsync).
        AppendLine("if (_policy is not null && !await _policy.IsAllowedAsync(TagValue, ct).ConfigureAwait(false))");
        IncreaseIndent();
        AppendLine("return Result<Guid, IError>.Failure(new ForbiddenError { Resource = \"Tag value not allowed\" });");
        DecreaseIndent();
        AppendLine();

        // Normalize tag value — policy override wins, else default trim/lowercase.
        var defaultNormalize = _model.CaseSensitive
            ? "TagValue.Trim()"
            : "TagValue.Trim().ToLowerInvariant()";
        if (_model.CaseSensitive)
        {
            // ITagPolicy.Normalize lower-cases by default, so ANY registered policy that does not
            // override it silently undid CaseSensitive = true. The option is the entity's decision
            // and wins: a policy that genuinely wants to fold case must do it in its own Normalize
            // and the entity must not ask for case sensitivity.
            AppendLine($"var normalizedValue = {defaultNormalize};");
        }
        else
        {
            AppendLine($"var normalizedValue = _policy is not null ? _policy.Normalize(TagValue) : {defaultNormalize};");
        }
        AppendLine("var displayValue = TagValue.Trim();");
        AppendLine();
    }

    private void RenderAddBody()
    {
        AppendLine($"public required {_model.SimpleIdType} {_model.ParentFkPropertyName} {{ get; init; }}");
        AppendLine("public required string TagValue { get; init; }");
        AppendLine();

        RenderRetriableExecute("Result<Guid, IError>");
        Block(() =>
        {
            RenderPolicyGateAndNormalize();

            RenderLimitTransactionOpen();

            // Find or create tag
            var scope = ScopeLiteral;

            AppendLine($"var tag = await _db.Set<{_model.TagTypeName}>()");
            AppendLine($"    .FirstOrDefaultAsync(t => t.Value == normalizedValue && t.Scope == {scope}, ct).ConfigureAwait(false);");
            AppendLine("var isNewTag = tag is null;");
            AppendLine();

            // Idempotency is checked BEFORE the per-entity limit: re-applying a tag the entity already
            // carries adds nothing, so an entity sitting exactly at the limit must still answer with the
            // existing tag id instead of a 403 about a limit this call would not cross.
            AppendLine("if (tag is not null)");
            Block(() =>
            {
                AppendLine($"var alreadyTagged = await _db.Set<{_model.JunctionTypeName}>()");
                AppendLine($"    .AnyAsync(j => j.{_model.ParentFkPropertyName} == {_model.ParentFkPropertyName} && j.TagId == tag.Id, ct).ConfigureAwait(false);");
                AppendLine("if (alreadyTagged)");
                IncreaseIndent();
                AppendLine("return tag.Id; // idempotent — already tagged");
                DecreaseIndent();
            });
            AppendLine();

            // Check max per entity — only now, when the call would genuinely add one.
            if (_model.MaxPerEntity > 0)
            {
                AppendLine($"var currentCount = await _db.Set<{_model.JunctionTypeName}>()");
                AppendLine($"    .CountAsync(j => j.{_model.ParentFkPropertyName} == {_model.ParentFkPropertyName}, ct).ConfigureAwait(false);");
                AppendLine($"if (currentCount >= {_model.MaxPerEntity})");
                IncreaseIndent();
                AppendLine($"return Result<Guid, IError>.Failure(new ForbiddenError {{ Resource = \"Tag limit ({_model.MaxPerEntity})\" }});");
                DecreaseIndent();
                AppendLine();
            }

            AppendLine("if (tag is null)");
            Block(() =>
            {
                // AllowCustom == false → curated taxonomy: never mint tags on the fly.
                if (!_model.AllowCustom)
                {
                    AppendLine($"return Result<Guid, IError>.Failure(NotFoundError.For(\"{_model.TagTypeName}\", normalizedValue));");
                    return;
                }

                AppendLine($"tag = new {_model.TagTypeName}");
                AppendLine("{");
                IncreaseIndent();
                AppendLine("Value = normalizedValue,");
                AppendLine("DisplayValue = displayValue,");
                AppendLine($"Scope = {scope},");
                AppendLine("CreatedAt = _clock.UtcNow,");
                AppendLine("CreatedBy = _currentUser.Id,");
                AppendLine("UsageCount = 1, // first usage — the junction below is created in the same commit");
                DecreaseIndent();
                AppendLine("};");
                AppendLine($"_db.Set<{_model.TagTypeName}>().Add(tag);");
            });
            AppendLine();

            // Create junction
            AppendLine($"var junction = new {_model.JunctionTypeName}");
            AppendLine("{");
            IncreaseIndent();
            AppendLine($"{_model.ParentFkPropertyName} = {_model.ParentFkPropertyName},");
            AppendLine("TagId = tag.Id,");
            AppendLine("AddedAt = _clock.UtcNow,");
            AppendLine("AddedBy = _currentUser.Id,");
            DecreaseIndent();
            AppendLine("};");
            AppendLine($"_db.Set<{_model.JunctionTypeName}>().Add(junction);");
            AppendLine();
            // An in-memory `UsageCount++` on the tracked entity is a read-modify-write that loses
            // updates under concurrent tagging, so an existing tag is incremented DB-side. That
            // statement executes immediately, while the junction row would only be written by the
            // invoker's SaveChanges afterwards: if that commit failed, the counter stayed raised
            // forever. Both now run inside one transaction owned by this action.
            if (_model.MaxPerEntity > 0)
            {
                // Serializable turns a lost race into a refusal by the database. Surfacing it as a 409
                // rather than a 500 is the difference between "retry this" and "something broke".
                AppendLine("try");
                Block(() =>
                {
                    RenderTransactionalCommit(
                        () =>
                        {
                            AppendLine("if (!isNewTag)");
                            Block(() =>
                            {
                                AppendLine($"await _db.Set<{_model.TagTypeName}>().Where(t => t.Id == tag.Id)");
                                AppendLine("    .ExecuteUpdateAsync(s => s.SetProperty(t => t.UsageCount, t => t.UsageCount + 1), ct).ConfigureAwait(false);");
                            });
                        });
                });
                AppendLine("catch (global::System.Exception ex) when (IsSerializationConflict(ex))");
                Block(() =>
                {
                    AppendLine($"return Result<Guid, IError>.Failure(new ConflictError {{ EntityType = \"{_model.JunctionTypeName}\", EntityId = {_model.ParentFkPropertyName}.ToString() }});");
                });
                AppendLine();
            }
            else
            {
                RenderTransactionalCommit(
                    () =>
                    {
                        AppendLine("if (!isNewTag)");
                        Block(() =>
                        {
                            AppendLine($"await _db.Set<{_model.TagTypeName}>().Where(t => t.Id == tag.Id)");
                            AppendLine("    .ExecuteUpdateAsync(s => s.SetProperty(t => t.UsageCount, t => t.UsageCount + 1), ct).ConfigureAwait(false);");
                        });
                    });
            }
            AppendLine();
            AppendLine($"if (_policy is not null) await _policy.OnTagAddedAsync({_model.ParentFkPropertyName}, tag.Id, normalizedValue, ct).ConfigureAwait(false);");
            AppendLine("return tag.Id;");
        });
    }

    private void RenderRemoveBody()
    {
        AppendLine($"public required {_model.SimpleIdType} {_model.ParentFkPropertyName} {{ get; init; }}");
        AppendLine("public required Guid TagId { get; init; }");
        AppendLine();

        RenderRetriableExecute("VoidResult<IError>");
        Block(() =>
        {
            RenderPolicyResolveVoid();

            AppendLine($"var junction = await _db.Set<{_model.JunctionTypeName}>()");
            AppendLine($"    .FirstOrDefaultAsync(j => j.{_model.ParentFkPropertyName} == {_model.ParentFkPropertyName} && j.TagId == TagId, ct).ConfigureAwait(false);");
            AppendLine();
            AppendLine("if (junction is null)");
            IncreaseIndent();
            AppendLine($"return VoidResult<IError>.Failure(NotFoundError.For(\"{_model.JunctionTypeName}\", $\"{{TagId}}\"));");
            DecreaseIndent();
            AppendLine();
            AppendLine($"_db.Set<{_model.JunctionTypeName}>().Remove(junction);");
            AppendLine();
            AppendLine($"var tag = await _db.Set<{_model.TagTypeName}>().FindAsync(new object[] {{ TagId }}, ct).ConfigureAwait(false);");
            AppendLine();
            // Same reasoning as the add: the DB-side decrement and the junction removal must land
            // together, or a failed commit leaves the counter permanently below the real usage.
            RenderTransactionalCommit(
                () =>
                {
                    AppendLine($"await _db.Set<{_model.TagTypeName}>().Where(t => t.Id == TagId && t.UsageCount > 0)");
                    AppendLine("    .ExecuteUpdateAsync(s => s.SetProperty(t => t.UsageCount, t => t.UsageCount - 1), ct).ConfigureAwait(false);");
                },
                () =>
                {
                    // A curated taxonomy (AllowCustom = false) is seeded by the application and recreated by
                    // no endpoint: deleting a tag whose last link went would erode it for good.
                    if (!_model.AllowCustom)
                        return;

                    // A tag nobody uses is noise: with AllowCustom on every typo would otherwise leave a
                    // permanent row, and no endpoint curates the catalogue. This runs AFTER the save —
                    // the junction row must already be gone for the check to mean anything — but still
                    // inside the transaction, so unlink and cleanup commit together.
                    AppendLine($"var stillLinked = await _db.Set<{_model.JunctionTypeName}>()");
                    AppendLine("    .AnyAsync(j => j.TagId == TagId, ct).ConfigureAwait(false);");
                    AppendLine("if (!stillLinked)");
                    Block(() =>
                    {
                        AppendLine($"await _db.Set<{_model.TagTypeName}>().Where(t => t.Id == TagId && t.UsageCount <= 0)");
                        AppendLine("    .ExecuteDeleteAsync(ct).ConfigureAwait(false);");
                    });
                });
            AppendLine();
            // Commit is owned by the DomainActionInvoker (single SaveChangesAsync after Execute). Do NOT save here.
            AppendLine($"if (_policy is not null) await _policy.OnTagRemovedAsync({_model.ParentFkPropertyName}, TagId, tag?.Value ?? string.Empty, ct).ConfigureAwait(false);");
            AppendLine("return Success;");
        });
    }


    private void RenderPolicyResolve()
        // Must come from the application container: the DbContext's IInfrastructure provider is
        // EF Core's *internal* one, where a consumer's AddScoped<ITagPolicy<T>,…> never lands.
        => AppendLine($"var _policy = (ITagPolicy<{_model.SimpleIdType}>?)_services.GetService(typeof(ITagPolicy<{_model.SimpleIdType}>));");

    private void RenderPolicyResolveVoid() => RenderPolicyResolve();
}

internal enum TagActionKind
{
    Add,
    Remove
}
